const SRF='https://www.srf.ch/play/tv/roemer-in-der-schweiz/video/die-kelten-und-die-roemer?urn=urn:srf:video:3da18acb-1a0a-4cab-97ce-0b0fb3f4f4e4';
const stations=[
{title:'Mythos oder Spur?',tag:'Das erste Fundstück',intro:'Im Museum steht: «Die Kelten waren nur wilde Barbaren.» Deine Mission: Prüfe dieses Bild. Sammle an jeder Station Belege für ein genaueres Urteil.',note:'Die Präsentation startet mit Vorstellungen über Gallier: Dorf, Druide, Zaubertrank und Kampf gegen Rom. Das sind zunächst Bilder im Kopf. Ob sie historisch tragen, muss erst geprüft werden.',source:'PPP_Kelten (1).pptx, Folien 3–4; Die Kelten.docx, Grundzüge und Religion.',tasks:[
{type:'choice',q:'Welche Aussage gehört zur erfundenen Comicwelt?',options:['Druiden erfüllten religiöse Aufgaben.','Ein Zaubertrank machte die Gallier unbesiegbar.','Keltische Siedlungen konnten befestigt sein.'],answer:1,why:'Der Zaubertrank ist eine Erfindung der Asterix-Comics. Druiden und befestigte Siedlungen sind dagegen historisch belegt.'},
{type:'multi',q:'Welche Spuren widersprechen dem Wort «nur» in «nur wilde Krieger»?',options:['Spezialisierte Eisenverarbeitung','Eigene Münzprägung','Weiträumiger Handel','Kriegerische Auseinandersetzungen'],answer:[0,1,2],why:'Handwerk, Münzen und Handel zeigen eine vielseitige Gesellschaft. Kriege gab es ebenfalls; sie beschreiben aber nicht das gesamte Leben.'},
{type:'choice',q:'Wie lassen sich Helvetier und Kelten sinnvoll unterscheiden?',options:['Alle Kelten waren Helvetier.','Die Helvetier waren eine keltische Gruppe; daneben gab es andere.','Die Helvetier waren ein römischer Beruf.'],answer:1,why:'Die Helvetier gehörten zu den keltischen Gruppen. Auf dem Gebiet der heutigen Schweiz lebten auch andere Gruppen, etwa Rauriker und Lepontier (SRF, 01:02–01:50).'}]},
{title:'Zeitspuren',tag:'Schicht für Schicht',intro:'Ein Fund verrät mehr, wenn du seine Zeit kennst. Ordne die grossen Veränderungen der Eisenzeit.',note:'In der Hallstattzeit wurde Eisen für Geräte und Waffen wichtiger. Ab dem 5. Jahrhundert v. Chr. breitete sich die Latènekultur aus. Später entstanden grosse befestigte Zentren, die Oppida. 58 v. Chr. besiegte Caesar die Helvetier.',source:'Die Kelten.docx, frühe und späte Eisenzeit; HLS, Latènezeit.',tasks:[
{type:'order',q:'Bringe die Ereignisse in die Reihenfolge: vom ältesten zum jüngsten.',items:['Caesar besiegt die Helvetier (58 v. Chr.).','Eisen gewinnt an Bedeutung (8. Jh. v. Chr.).','Oppida sind weit verbreitet (spätes 2.–1. Jh. v. Chr.).','Latènekultur breitet sich aus (ab 5. Jh. v. Chr.).'],answer:[1,3,2,0],why:'Bei Jahreszahlen vor Christus liegt die grössere Zahl weiter zurück. Die Reihenfolge lautet: frühe Eisenzeit → Latènekultur → Oppida → 58 v. Chr.'},
{type:'match',q:'Ordne die Merkmale den beiden Kulturen zu.',items:['Salzbergbau am namengebenden Ort','Geometrische Zierformen','Pflanzliche Motive und verborgene Gesichter','Benannt nach einem Fundort am Neuenburgersee'],categories:['Hallstatt','Latène'],answer:[0,0,1,1],why:'Hallstatt steht hier für Salzreichtum und geometrische Muster. La Tène gab der späteren Kultur mit oft mehrdeutigen, pflanzlichen und figürlichen Darstellungen ihren Namen.'},
{type:'choice',q:'Warum ist «Hallstatt wurde an einem Tag durch Latène ersetzt» falsch?',options:['Archäologische Kulturen beschreiben Veränderungen, die sich allmählich und regional unterschiedlich vollzogen.','Beide Begriffe bezeichnen römische Kaiser.','Vor Christus gab es keine Veränderungen.'],answer:0,why:'Die Bezeichnungen helfen, materielle Merkmale zu ordnen. Sie markieren keinen plötzlichen Austausch einer gesamten Bevölkerung.'}]},
{title:'Das weisse Gold',tag:'Werkstatt und Handelsplatz',intro:'Eine Stadt braucht Nahrung, Werkzeuge und Austausch. Verknüpfe die Gegenstände mit ihrer Wirkung.',note:'Salz machte Lebensmittel haltbarer und war ein begehrtes Handelsgut. Eisenwerkzeuge erleichterten die Landwirtschaft. Drehmühlen halfen bei der Getreideverarbeitung. Münzen und importierte Gefässe weisen auf wirtschaftlichen Austausch hin.',source:'Die Kelten.docx, Hallstatt-Kultur; Wirtschaft und Handel; Oppida.',tasks:[
{type:'match',q:'Was bewirkt welcher Gegenstand?',items:['Salz','Eiserne Pflugschar','Drehmühle','Fibel'],categories:['Kleidung zusammenhalten','Getreide mahlen','Lebensmittel konservieren','Boden bearbeiten'],answer:[2,3,1,0],why:'Salz konserviert, die Pflugschar bearbeitet den Boden, die Drehmühle mahlt und die Fibel hält Kleidungsstücke zusammen.'},
{type:'choice',q:'Du findest eine importierte Weinamphore in einem reichen Grab. Was ist die vorsichtigste Schlussfolgerung?',options:['Alle Menschen tranken täglich griechischen Wein.','Das ist ein Hinweis auf Kontakte und Zugang zu einem Importgut.','Der verstorbene Mensch muss in Griechenland geboren sein.'],answer:1,why:'Ein Importgegenstand belegt Kontakte. Ein einzelnes reiches Grab beweist weder die Herkunft einer Person noch den Alltag der gesamten Bevölkerung.'},
{type:'multi',q:'Welche Gründe könnten das Leben in einem Oppidum attraktiv gemacht haben?',options:['Schutz durch Befestigungen','Nähe zu Märkten und Handwerk','Gemeinsame religiöse und politische Zentren','Eine bereits erfundene elektrische Strassenbeleuchtung'],answer:[0,1,2],why:'Schutz, wirtschaftliche Vorteile und zentrale Funktionen sind plausible Gründe. Welche Motive im Einzelfall entscheidend waren, bleibt oft unklar.'}]},
{title:'Tatort Bern',tag:'Der SRF-Videoauftrag',intro:'Begleite Angela Haas auf die Engehalbinsel und ins Museum. Sieh dir die Ausschnitte an und prüfe, was Funde wirklich verraten.',video:true,note:'Falls das Video nicht verfügbar ist: Fibeln halten Kleidung zusammen. Im Heiligtum wurden unter anderem Tierknochen gefunden; ein gemeinsames Opfermahl ist eine Deutung. Nach der römischen Eroberung lebte die lokale Bevölkerung weiter. Keltische und römische Einflüsse verbanden sich.',source:'SRF: Die Kelten und die Römer (2024), 02:08–02:31, 07:09–07:39 und 10:31–11:21. Fragen anhand der deutschen Untertitel geprüft.',tasks:[
{type:'choice',q:'02:08–02:31 · Mit welchem heutigen Gegenstand wird eine Fibel verglichen?',options:['Mit einer Sicherheitsnadel','Mit einem Reissverschluss','Mit einer Armbanduhr'],answer:0,why:'Die Expertin vergleicht die Fibel mit einer Sicherheitsnadel. Sie hat eine praktische und eine schmückende Funktion.'},
{type:'match',q:'07:09–07:39 · Trenne den Fund von seiner Deutung.',items:['Im Graben lagen Bärenknochen.','Vielleicht wurde ein Bär gemeinsam mit den Göttern verspeist.'],categories:['Archäologischer Fund','Interpretation'],answer:[0,1],why:'Die Knochen wurden gefunden. Das Opfer und das gemeinsame Mahl sind eine Interpretation; die Expertin kennzeichnet dies ausdrücklich als Annahme.'},
{type:'choice',q:'10:31–11:21 · Was geschah nach der römischen Eroberung?',options:['Alle Kelten verschwanden sofort.','Die Menschen lebten weiter; aus gegenseitigen Einflüssen entstand eine gallorömische Kultur.','Kelten und Römer hatten nie miteinander Handel getrieben.'],answer:1,why:'Politische Eroberung bedeutet nicht, dass eine Bevölkerung verschwindet. Der Film beschreibt Weiterleben und kulturellen Austausch.'}]},
{title:'Wer erzählt?',tag:'Das Quellenlabor',intro:'Caesar kämpfte gegen keltische Gruppen. Diodor schrieb aus griechischer Perspektive. Wie verändert ihr Blick die Geschichte?',note:'Diodor schildert unter anderem Goldschmuck und religiöse Scheu, verbindet das aber mit pauschalen Urteilen über die Kelten. Caesar stellt Tapferkeit und kriegerische Bedrohung heraus. Felix Müller betont die Aussenperspektive antiker Texte und die Deutungsgrenzen archäologischer Funde.',source:'Die Kelten.docx, ergänzende Texte von Diodor, Caesar und Felix Müller (2012). Zusammenfassungen, keine wörtlichen Zitate.',tasks:[
{type:'choice',q:'Caesar schildert seine Gegner als besonders tapfer. Was sollte eine Quellenkritik berücksichtigen?',options:['Ein Feldherr ist automatisch neutral.','Ein mächtiger Gegner kann den eigenen Sieg grösser erscheinen lassen.','Caesar kann deshalb keinerlei brauchbare Informationen liefern.'],answer:1,why:'Caesars politische und militärische Rolle ist relevant. Das mögliche Interesse an Selbstdarstellung macht eine kritische Prüfung nötig, aber nicht jede Einzelinformation falsch.'},
{type:'multi',q:'Welche Fragen helfen beim Vergleich von Diodor und Caesar?',options:['Wer schreibt, wann und in welcher Rolle?','Welche Wertungen und Verallgemeinerungen fallen auf?','Welche archäologischen Funde stützen oder begrenzen die Aussagen?','Welcher Autor klingt für mich sympathischer?'],answer:[0,1,2],why:'Quellenkritik prüft Entstehung, Perspektive, Sprache und unabhängige Belege. Sympathie ist kein verlässliches Wahrheitskriterium.'},
{type:'choice',q:'Ähnliche Schmuckstücke tauchen in mehreren Regionen auf. Was folgt nach Müllers Überlegungen daraus?',options:['Die Regionen gehörten sicher zu demselben Stamm.','Möglich sind Handel, gemeinsame Bräuche oder soziale Verbindungen; der Befund allein entscheidet das nicht.','Die Funde haben keinerlei Aussagewert.'],answer:1,why:'Verbreitungsmuster sind wertvolle Hinweise. Sie lassen sich aber nicht automatisch mit Stammesgrenzen gleichsetzen.'}]},
{title:'Dein Museumsurteil',tag:'Die letzte Vitrine',intro:'Du hast die Spuren gesammelt. Jetzt entsteht aus dem Klischee ein begründetes Geschichtsbild.',note:'Druiden waren unter anderem Priester, Richter und Lehrer. Keltische Kunst kann mehrdeutig sein. Der Begriff «Hochkultur» arbeitet mit Kriterien wie Städten, Arbeitsteilung und Schrift, ist aber umstritten, wenn daraus eine Rangordnung menschlicher Kulturen gemacht wird.',source:'Die Kelten.docx, Religion und Mythen; Müller; Arbeitsaufträge 10–12. Einordnung des Hochkulturbegriffs: didaktische Ergänzung. HLS, Kelten (Schriftgebrauch).',tasks:[
{type:'multi',q:'Welche Tätigkeiten schreiben die Materialien den Druiden zu?',options:['Religiöse Kulte leiten','Recht sprechen','Lehren und Wissen weitergeben','Historisch nachgewiesenen Zaubertrank brauen'],answer:[0,1,2],why:'Druiden werden als Priester, Richter, Gelehrte und Lehrer beschrieben. Der Zaubertrank gehört zur Comicwelt.'},
{type:'choice',q:'«Keine überlieferte eigene Geschichtsschreibung» bedeutet …',options:['… dass niemand keltische Sprache aufschreiben konnte.','… nicht dasselbe wie «keinerlei Schriftgebrauch».','… dass die Gesellschaft keine Kultur besass.'],answer:1,why:'Schriftgebrauch und Geschichtsschreibung sind verschiedene Dinge. Inschriften und Berichte über Schriftgebrauch sind bekannt. Das Fehlen eigener erhaltener Geschichtswerke ist kein Werturteil über eine Kultur.'},
{type:'choice',q:'Welche Beschriftung verdient einen Platz in der Ausstellung?',options:['Die Kelten waren ein einheitliches Volk ohne Handwerk und Handel.','Keltische Gruppen verbanden Handwerk, Handel und unterschiedliche Lebensweisen. Unser Bild entsteht aus Funden und kritisch zu lesenden Texten.','Die Kelten waren friedlich, deshalb müssen sämtliche Kriegsberichte erfunden sein.'],answer:1,why:'Ein begründetes Urteil berücksichtigt Vielfalt, wirtschaftliche Leistungen und Konflikte ebenso wie die Grenzen unserer Quellen.'}]}
];
